SELECT 
FROM points_transaction pt
LEFT JOIN sys_user su ON su.id = pt.user_id
WHERE pt.user_id = #{userId}

    AND pt.direction = #{query.direction}


    AND pt.biz_type = #{query.bizType}


    AND pt.created_at >= #{query.startTime}


    AND pt.created_at <= #{query.endTime}

ORDER BY pt.created_at DESC, pt.id DESC

SELECT 
FROM points_transaction pt
LEFT JOIN sys_user su ON su.id = pt.user_id
WHERE pt.user_id = #{userId}
  AND pt.id = #{id}
LIMIT 1

SELECT pa.user_id, pa.balance, pa.total_income, pa.total_expense, COALESCE(NULLIF(su.realname, ''), su.username) AS nickname, su.username, su.email, su.avatar, pa.updated_at FROM user_points_account pa LEFT JOIN sys_user su ON su.id = pa.user_id
AND ( pa.user_id LIKE CONCAT('%', #{query.keyword}, '%') OR su.username LIKE CONCAT('%', #{query.keyword}, '%') OR su.realname LIKE CONCAT('%', #{query.keyword}, '%') OR su.email LIKE CONCAT('%', #{query.keyword}, '%') )
AND pa.balance >= #{query.minBalance}
AND pa.balance <= #{query.maxBalance}
ORDER BY pa.updated_at DESC, pa.id DESC

SELECT 
FROM points_transaction pt
LEFT JOIN sys_user su ON su.id = pt.user_id


        AND (
            pt.transaction_no LIKE CONCAT('%', #{query.keyword}, '%')
            OR pt.user_id LIKE CONCAT('%', #{query.keyword}, '%')
            OR su.username LIKE CONCAT('%', #{query.keyword}, '%')
            OR su.realname LIKE CONCAT('%', #{query.keyword}, '%')
        )


        AND pt.direction = #{query.direction}


        AND pt.biz_type = #{query.bizType}


        AND pt.status = #{query.status}


        AND pt.created_at >= #{query.startTime}


        AND pt.created_at <= #{query.endTime}


ORDER BY pt.created_at DESC, pt.id DESC
